      "favorited" : false,
      "full_text" : "• 于是就要把丁塑造成“纯粹低俗、无耻”“穷闲”“靠裸露吸关注”的形象，好让自己在心理上有“我高贵”“我有底气”，从而逃避“颜值不如人”带来的自我否定。\n• 在整段攻击里，她不断用“如歌高高在上”“我看你疯癫”“我掌控一切”的口吻，让观众觉得“她一点都不在怕”“她随时能碾压对方”。 https://t.co/Njh57qULtL",
