      "full_text" : "地方的民代實際體感，抗中保台在網路有回響，在地方沒什麼票。尤其越年輕人，越是票房毒藥。關心學測、志願、就業、生活都關心不完了。\n青鳥有稍微扭轉這種局面，但應該是放軟身段，讓年輕人因為你提供的內容有意思、有趣、稀奇…",
