      "full_text" : "支人的可恶就在于无时无刻不在压制你。以前认识一对华人夫妇，六十多岁，男的原本是山东的，俩人平时看着还行。有一次我跟他俩聊天聊到说想去大学读书，那男的说，等你读出来都多大了？好好带你孩子培养孩子吧。我跟美国本地其他人种说起读书，他们都说：School is amazing! Go for it! You can do i",
