      "full_text" : "我只能偷偷告诉各位\n牛市开始了   牛市第一波回调结束\n\n整个加密华人圈，估计也只有我敢喊牛来了吧。\n山寨狂暴之牛来了\n\n#BTC      #ETH #BNB    $CHZ  $GALA  $Manta  $EOS",
