      "full_text" : "电影看完了，基努的短信我还没有回复。我太纠结了我真的整不会了从来没有和男人一起去看电影。说来真的丢人啊。接下来怎么回短信？\n基努其实性格很像我初恋，那种一开口就很温柔，不说话时安安静静的那种。我暗恋我初恋青梅竹马十七年，但他结婚了我都没敢表白。…在想要不一个人去看电影还是唱歌呢",
