      "favorited" : false,
      "full_text" : "隨著AI的進步，我覺得那種認證是否為機器人真正該放的問題\n\n不是什麼＊請找出含有「人行道」的相片＊\n\n而應該要放\n＊請問以下哪些不是代指「貓」？\n\n小王八蛋、一坨、毛球、咪咪、捏扣、會呼吸的毛、混世大魔王、球＊\n或\n＊請問以下哪些是今年的迷因？＊\n\n這種問題才對",
      "lang" : "zh"
