      "full_text" : "整个社会把高考看得如此重要是不健康的。\n你以为是学历让你实现了阶层流动，并不是。让你实现阶层流动的是市场化，是有更多需要你知识的岗位的诞生。否则你就是读到博士，最后也是知识青年上山下乡2.0。",
