      "full_text" : "看了下Taiko团队是有公关负责人的，\n就Taiko团队目前的发言，\n我没有看到这位公关小姐姐的“专业性”。\n\n俺的评价是：\nTaiko团队现阶段的发言，只会让华人团队在Web3，特别是华语区的路，更难走。",
