      "full_text" : "包場看電影的重點我還是放在電影本身內容，以及票房能夠直接給代理商/製作方/原作方的回饋\n\n其他附加價值就是包場主題/和同好齊聚一堂有相近共鳴，特典和紙片交流等等\n\n買菜（電影）送蔥（官方特典）能增加買氣，但沒有蔥就不買菜的風氣我一直是表示理解但很不能體會",
