      "full_text" : "之前回趟老家办事,政府大楼里全是织女公务员,比例失调.\n\n公务员这个职业,吹吹空调,没有业绩压力,拿纳税人的钱,吸社会的血,自己不创造经济价值.这不是和织女平日里一摸一样?\n\n难怪织女都有考公情节,这帮人在如何吸血这方面是最绞尽脑汁最精明的,和一堆国男工程师码农相比,妥妥社会负资产",
