      "full_text" : "人渣中的人渣司马南以为自己坐拥2000万粉丝一乎百应，不知道自己算个什么东西吃几两干饭，居然拍了部电影《青山之外》，结果票房几乎为零，提前下档。唐国强自导一部电影请他站台，票房竟只有60万。看来夹头是真真切切的票房杀手。他就不想想，他的那些猪一样的粉丝怎么会有雅兴去看电影？",
