      "full_text" : "今晚站桩看老电影《荆轲刺秦王》，人物略显精神之外，布景真是好看……\n答：也不行啊，正史记载秦王绕着殿内柱子跑躲避，怎么着最小也得给安排一根直径四五米的宫殿柱子吧，现在都参照紫禁城柱子的标准，柱子不过一米的直径，怎么跑，一个回身就碰面了.......想象力匮乏啊。",
