      "full_text" : "‘’三，找出孙中山历史上的缺陷，加以攻击，以扰乱和降低汉人对他的崇拜。 四，大力追捧歌颂清朝的电影和电视剧，必要是可以集资找人拍，再发动全国的满人来捧场，从而造成清朝的热效应。让汉人的年轻一代去崇拜我们的祖先。在意识形态上给汉人洗脑‘’",
