      "full_text" : "据猫眼专业版数据，宫崎骏新作、刚刚获得第96届奥斯卡最佳动画长片奖的《你想活出怎样的人生》清明节单日票房破6866.2万，超《铃芽之旅》清明节票房成绩，成为中国影史清明节动画片票房冠军！",
