      "full_text" : "司马老师号称2亿粉丝，资本被迷住了，投了7000万回收30万票房。\n他们不知道屌丝除了仇恨一无所有，哪有钱去看你的吊毛电影。\n这股仇恨足以毁灭很多事物，却建设不了任何事业。",
