      "full_text" : "1）刚刚有点时间，好好说说大兵净多的事情，以及验证他的人设，也就是什么大红一师退役军人。本来这个人根本不会在我的时间线里出现，就算真实生活中，我和这种三十多岁还在混校园拿学历，没有任何实际工作经验的人是根本不会有接触的。更别提一个当了大头兵就退役，没有任何军衔的社会混子有交集",
