      "full_text" : "讲真\n我也想退网\n但是我舍不得女粉丝\n\n行情一暴涨暴跌就有很多女粉丝爆仓亏完了\n你想20来岁的女孩子\n就要一个人面对社会的毒打\n如果没人收留多惨\n实在看不下去 只能心软收留\n我不收留谁收留 好好抚贫",
