      "full_text" : "把一起看过的电影票根拍舍友桌子上\n“你怎么还留着?”\n“这是我们爱的证明啊。”\n“又不是开房记录，什么爱的证明（不屑）”\n“开房记录算什么爱的证明，充其量是做爱的证明吧。”\n舍友:轻轻地破防了",
