      "full_text" : "论meme币\n很多华人KOL们，说华人meme没有文化\n其实我买过的meme币，反而是老外的居多；\n我想说的是，老外的meme更没有文化\n你说 $doge $shib 有什么文化？\n$pepe $dome 又有什么文化？\n\n如果你进过老外的TG群，你会突然觉得自己英语老好了，为什么呢？…",
