      "full_text" : "tiktok和temu现在在美国好比冷战时期，苏联一半的人口收听美国的电台，在美国人开的市场买东西，这苏联能不方么？但是你苏联自己的电台只会天天吹阿富汗大捷多民族和睦，勃列日涅夫好赫鲁晓夫傻逼，自己国营百货商场的东西还死贵。这次国家杜马堵了tt的话，只会更多人收听美国敌台，走私美国货",
