      "full_text" : "进入20世纪，还有超过90%的美国人说相信上帝，其中绝大多数人是基督徒。经历了60年代的性解放运动，经历了无根和焦虑以及反战的70年代，经历了“贪婪是好的”80年代，这个数字依然保持稳定。但在1990年代初，美国人与信仰的历史纽带嗄然断裂！无宗教信仰开始兴起，到21世纪初，宣称不信奉任何宗教",
