      "full_text" : "可能过于ambitieuse了，但我真是这么想的。\n\n如果我未来真的有足够强大的能力，那我大概会去从政，或者尽可能促进中法交流，帮法国这边的华人华裔拧绳。\n\n次之，可能会开一个IT的公司，在能力达标的情况下，优先招trans。\n\n或者，好好活下去，就是足够有意义的事。\n\n这三者，从极小概率到极大概率2333",
